223				}
224				if got.Confirmed || got.Reason != ReasonTotalOverflow {
225					t.Fatalf("溢出请求不能留下已确认记录: %+v", got)
226				}
227				if got.UnitPrice != 0 || got.Total != 0 {
228					t.Fatalf("溢出拒绝的单价/总价应为零: %d/%d", got.UnitPrice, got.Total)
229				}
230			})
231		}
232	}
