129				t.Fatalf("%s: 请求来源未保留: %+v vs %+v", c.name, out.Request, req)
130			}
131			if !out.AcceptedAt.Equal(c.instant) {
132				t.Fatalf("%s: 受理时刻=%v, want %v", c.name, out.AcceptedAt, c.instant)
