169				want{true, 180, 720, ReasonNone},
170			},
171		}
172		// 同一实际时刻的三种表示：东八区、UTC、零时区偏移的另一命名时区。
173		repr := func(t time.Time) []time.Time {
174			return []time.Time{
175				t,
176				t.UTC(),
177				t.In(time.FixedZone("UTC+0", 0)),
178			}
179		}
180		for _, c := range instants {
181			reprs := repr(c.instant)
182			for i := 1; i < len(reprs); i++ {
183				// 测试前提：表示不同时刻相同
184				if !reprs[0].Equal(reprs[i]) {
185					t.Fatalf("%s: 测试前提不成立，表示不代表同一时刻", c.name)
186				}
187			}
188			var firstOld, firstNew Outcome
189			for r, instant := range reprs {
190				setNow(instant)
191				outOld, err := b.Quote(QuoteRequest{
192					RequestID: fmt.Sprintf("tz-%s-old-%d", c.name, r),
193					ItemID:    "seat", VersionID: "seat-v1", Quantity: 4,
194				})
195				if err != nil {
196					t.Fatalf("%s 表示%d 旧版: %v", c.name, r, err)
197				}
198				outNew, err := b.Quote(QuoteRequest{
199					RequestID: fmt.Sprintf("tz-%s-new-%d", c.name, r),
200					ItemID:    "seat", VersionID: "seat-v2", Quantity: 4,
201				})
202				if err != nil {
203					t.Fatalf("%s 表示%d 新版: %v", c.name, r, err)
204				}
205				check := func(out Outcome, w want, who string) {
206					t.Helper()
207					if out.Confirmed != w.confirmed || out.UnitPrice != w.unitPrice ||
208						out.Total != w.total || out.Reason != w.reason {
209						t.Fatalf("%s 表示%d %s: got %+v, want confirmed=%v price=%d total=%d reason=%q",
210							c.name, r, who, out, w.confirmed, w.unitPrice, w.total, w.reason)
211					}
212				}
213				check(outOld, c.oldV, "旧版")
214				check(outNew, c.newV, "新版")
215				if r == 0 {
216					firstOld, firstNew = outOld, outNew
217					continue
218				}
219				// 确认状态、金额、拒绝原因与时区表示无关
220				if outOld.Confirmed != firstOld.Confirmed || outOld.UnitPrice != firstOld.UnitPrice ||
221					outOld.Total != firstOld.Total || outOld.Reason != firstOld.Reason {
222					t.Fatalf("%s: 旧版结果随时区表示变化: %+v vs %+v", c.name, firstOld, outOld)
223				}
224				if outNew.Confirmed != firstNew.Confirmed || outNew.UnitPrice != firstNew.UnitPrice ||
225					outNew.Total != firstNew.Total || outNew.Reason != firstNew.Reason {
226					t.Fatalf("%s: 新版结果随时区表示变化: %+v vs %+v", c.name, firstNew, outNew)
227				}
228			}
229		}
230	}
231	
232	// 新版已有效时，指定旧版的报价必须保留旧版来源并拒绝，不能自动换版计算。
233	func TestHandoffNoAutoVersionSwitch(t *testing.T) {
234		b, _ := newHandoffBook(t, handoffPoint.Add(time.Hour))
235	
236		out, err := b.Quote(QuoteRequest{
237			RequestID: "no-switch", ItemID: "seat", VersionID: "seat-v1", Quantity: 4,
238		})
239		if err != nil {
240			t.Fatalf("拒绝是正常受理，err 应为空: %v", err)
241		}
242		if out.Confirmed {
243			t.Fatalf("旧版已失效，不能确认: %+v", out)
244		}
245		if out.Reason != ReasonVersionExpired {
246			t.Fatalf("拒绝原因=%q, want %q", out.Reason, ReasonVersionExpired)
247		}
248		// 拒绝结果单价、总价均为 0，且来源仍是指定的旧版，未被换成新版。
249		if out.UnitPrice != 0 || out.Total != 0 {
250			t.Fatalf("拒绝结果金额应为 0: 单价=%d 总价=%d", out.UnitPrice, out.Total)
251		}
252		if out.Request.VersionID != "seat-v1" || out.Request.ItemID != "seat" || out.Request.Quantity != 4 {
253			t.Fatalf("拒绝结果必须保留旧版来源: %+v", out.Request)
254		}
255	}
256	
257	// 交接前确认的 600 分报价，交接后按原标识查询仍保留首次结果，不按当前费率重算。
258	func TestHandoffConfirmedQuoteSurvives(t *testing.T) {
259		acceptedAt := time.Date(2026, 3, 2, 10, 0, 0, 0, east8)
260		b, setNow := newHandoffBook(t, acceptedAt)
261	
262		req := QuoteRequest{RequestID: "keep-600", ItemID: "seat", VersionID: "seat-v1", Quantity: 4}
263		first, err := b.Quote(req)
264		if err != nil || !first.Confirmed {
265			t.Fatalf("交接前报价应确认: %v %+v", err, first)
266		}
267		if first.UnitPrice != 150 || first.Total != 600 {
268			t.Fatalf("交接前金额: 单价=%d 总价=%d", first.UnitPrice, first.Total)
269		}
270		if !first.AcceptedAt.Equal(acceptedAt) {
271			t.Fatalf("首次受理时刻: %v", first.AcceptedAt)
272		}
273	
274		// 推进到交接点之后：旧版已失效，新版 180 分已生效。
275		setNow(handoffPoint.Add(24 * time.Hour))
276	
277		got, err := b.Lookup("keep-600")
278		if err != nil {
279			t.Fatal(err)
280		}
281		if got != first {
282			t.Fatalf("历史报价被重算: %+v -> %+v", first, got)
283		}
284		if got.Request.VersionID != "seat-v1" || got.Request.Quantity != 4 ||
285			got.UnitPrice != 150 || got.Total != 600 || !got.AcceptedAt.Equal(acceptedAt) {
286			t.Fatalf("历史报价未保留原版本/数量/金额/受理时刻: %+v", got)
287		}
288	
289		// 原样重试同样返回首次结果，而不是按当前费率重算。
290		replay, err := b.Quote(req)
291		if err != nil {
292			t.Fatal(err)
293		}
294		if replay != first {
295			t.Fatalf("重试结果被重算: %+v -> %+v", first, replay)
296		}
297	}
