		}
		if gotFresh != fresh {
			t.Fatalf("%v 新标识查询结果不一致: %+v vs %+v", instant, fresh, gotFresh)
		}
		if gotOld == gotFresh {
			t.Fatalf("%v 两份结果应可稳定区分: %+v", instant, gotOld)
		}
	}

	// 两个时刻都走过后，原标识的结果依旧是 at(50) 的首次拒绝。
	final, err := b.Lookup("early")
	if err != nil {
		t.Fatal(err)
	}
	if final != first {
		t.Fatalf("原标识的最终结果被改写: %+v -> %+v", first, final)
	}
}

