495	func TestItemNotFound(t *testing.T) {
496		b := NewBook()
497		if _, err := b.ItemVersions("nope"); !errors.Is(err, ErrItemNotFound) {
498			t.Fatalf("want ErrItemNotFound, got %v", err)
