	}

	must(RegisterRequest{ItemID: "seat", VersionID: "new", UnitPrice: 1, Start: at(40), Replaces: "old"})
	views, _ = b.ItemVersions("seat")
	// 即使调用方给返回结果中的登记结束塞了值，再次查询仍应为 nil
	for i := range views {
		if views[i].VersionID == "old" {
			late := at(99)
			views[i].End = &late
			*views[i].EffectiveEnd = at(99)
